        $this->descripcion = null;
        $this->es_periodo_actual = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collDocPrestamos) {
                foreach ($this->collDocPrestamos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collPrestamos) {
                foreach ($this->collPrestamos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collServicios) {
                foreach ($this->collServicios as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collClPrestamos) {
                foreach ($this->collClPrestamos as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collFacturas) {
                foreach ($this->collFacturas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComEnviadas) {
                foreach ($this->collComEnviadas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComInternas) {
                foreach ($this->collComInternas as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collComRecibidas) {
                foreach ($this->collComRecibidas as $o) {
                    $o->clearAllReferences($deep);
                }
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collDocPrestamos instanceof PropelCollection) {
            $this->collDocPrestamos->clearIterator();
        }
        $this->collDocPrestamos = null;
        if ($this->collPrestamos instanceof PropelCollection) {
            $this->collPrestamos->clearIterator();
        }
        $this->collPrestamos = null;
        if ($this->collServicios instanceof PropelCollection) {
            $this->collServicios->clearIterator();
        }
        $this->collServicios = null;
        if ($this->collClPrestamos instanceof PropelCollection) {
            $this->collClPrestamos->clearIterator();
        }
        $this->collClPrestamos = null;
        if ($this->collFacturas instanceof PropelCollection) {
            $this->collFacturas->clearIterator();
        }
        $this->collFacturas = null;
        if ($this->collComEnviadas instanceof PropelCollection) {
            $this->collComEnviadas->clearIterator();
        }
        $this->collComEnviadas = null;
        if ($this->collComInternas instanceof PropelCollection) {
            $this->collComInternas->clearIterator();
        }
        $this->collComInternas = null;
        if ($this->collComRecibidas instanceof PropelCollection) {
            $this->collComRecibidas->clearIterator();
        }
        $this->collComRecibidas = null;
    }

